sys_script_client.script:
function onSubmit() {
    cleanPercent('u_limite_maximo');
    cleanPercent('u_comprometimento_rcl');
    cleanPercent('u_limite_prudencial');
    cleanPercent('u_limite_de_alerta');
    return true;
}

function cleanPercent(variableName) {
    let value = g_form.getValue(variableName);
    if (!value) return;

    value = value.replace('%', '').replace(',', '.').replace(/\./g, '').trim();

    if (!isNaN(value)) {
        let numericValue = parseFloat(value) / 100;
        g_form.setValue(variableName, numericValue.toString());
    } else {
        g_form.setValue(variableName, value);
    }
}
